DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT109-S3-Q3$pilot$ AND c.letter=$pilot$B$pilot$ AND c.choice_text=$pilot$The marsh hen’s call is harsh and repetitive, whereas the calls of many other marsh birds are pleasant and melodious.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT109-S3-Q3 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT109-S3-Q3$pilot$ AND c.letter=$pilot$C$pilot$ AND c.choice_text=$pilot$Unlike many small marsh birds, which dash along the banks of the marsh, the marsh hen remains completely still for long periods of time.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT109-S3-Q3 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT109-S3-Q3$pilot$ AND c.letter=$pilot$D$pilot$ AND c.choice_text=$pilot$Many marsh birds are most active during daylight hours, but the marsh hen is usually most active at night.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT109-S3-Q3 D'; END IF; END $guard$;
