INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $pilot$Given that ...$pilot$, $pilot$The marsh hen is the most common bird in Stillwater Marsh.$pilot$), (1, $pilot$How can it be that ...$pilot$, $pilot$It's seen less often than any other bird there, including smaller and rarer ones, even by experienced bird-watchers looking for it?$pilot$), (2, $pilot$Evaluate$pilot$, $pilot$We'd expect the most common bird to be the one people see most. So something about the marsh hen must make it hard to *see*, no matter how many there are.

What makes a bird hard to spot? It blends in. It doesn't move. It's out when people aren't. It stays hidden and rarely flies.

On EXCEPT questions, the four answers we eliminate usually come at the paradox from the same angle. Here that angle is "the marsh hen is hard to see."$pilot$), (3, $pilot$Goal$pilot$, $pilot$Eliminate four answers that give the marsh hen a reason to be hard to see. The correct answer will be neutral (nothing to do with being seen) or it will make the hen *easier* to notice.$pilot$)) v(position,label,body) WHERE q.qid=$pilot$PT109-S3-Q3$pilot$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
